import React, { useState, useRef, useEffect, useCallback } from 'react';
import { DragDropContext, Droppable, Draggable } from "@hello-pangea/dnd";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import GrantCard from "./GrantCard";
import { Award, Eye, FileEdit, Layers, Send, Archive, XCircle, HardHat, FileBarChart, CheckCircle, CalendarX } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import client from '@/api/client';
import { useToast } from "@/components/ui/use-toast";

const STATUSES = [
      { value: "discovery", label: "Discovery", icon: Layers },
        { value: "discovered", label: "Discovered", icon: Layers },
          { value: "interested", label: "Assess", icon: Eye },
            { value: "auto_applied", label: "Auto-Applied", icon: CheckCircle },
              { value: "drafting", label: "Drafting", icon: FileEdit },
                { value: "application_prep", label: "Application Prep", icon: FileEdit },
                  { value: "revision", label: "Revision", icon: HardHat },
                    { value: "portal", label: "Portal", icon: HardHat },
                      { value: "submitted", label: "Submitted", icon: Send },
                        { value: "pending_review", label: "Pending Review", icon: Eye },
                          { value: "follow_up", label: "Follow Up", icon: Send },
                            { value: "awarded", label: "Awarded", icon: Award },
                              { value: "report", label: "Reporting", icon: FileBarChart },
                                { value: "declined_no_review", label: "Declined (No Review)", icon: XCircle },
                                  { value: "declined", label: "Declined", icon: XCircle },
                                    { value: "closed", label: "Closed", icon: Archive },
                                      { value: "deadline_passed", label: "Deadline Passed", icon: CalendarX },
                                    ];

                                    // Legacy / pre-migration statuses that have no column of their own are
                                    // mapped to the closest visible column so historical grants never vanish
                                    // from the board. Every value in GRANT_STATUSES (backend/config/constants.js)
                                    // must resolve to a column here or via this alias map — counts must map 1:1
                                    // to backend rows (no silent drops).
                                    const STATUS_ALIASES = {
                                          app_prep: "application_prep",
                                            under_review: "pending_review",
                                              rejected: "declined",
                                                archived: "closed",
                                                };

                                    const statusColors = {
                                          discovery: "bg-gray-100 text-gray-900",
                                            discovered: "bg-slate-100 text-slate-900",
                                              interested: "bg-blue-100 text-blue-800",
                                                auto_applied: "bg-green-100 text-green-800",
                                                  drafting: "bg-purple-100 text-purple-800",
                                                    application_prep: "bg-yellow-100 text-yellow-800",
                                                      revision: "bg-orange-100 text-orange-800",
                                                        portal: "bg-orange-100 text-orange-800",
                                                          submitted: "bg-amber-100 text-amber-800",
                                                            pending_review: "bg-indigo-100 text-indigo-800",
                                                              follow_up: "bg-green-100 text-green-800",
                                                                awarded: "bg-emerald-100 text-emerald-800",
                                                                  report: "bg-teal-100 text-teal-800",
                                                                    declined_no_review: "bg-red-100 text-red-800",
                                                                      declined: "bg-red-100 text-red-800",
                                                                        closed: "bg-gray-100 text-gray-900",
                                                                          deadline_passed: "bg-rose-100 text-rose-800",
                                                                        };

                                                                        function PipelineSlider({ scrollRef }) {
                                                                              const [sliderValue, setSliderValue] = useState(0);
                                                                                const [visibleRange, setVisibleRange] = useState({ start: 0, end: 3 });

                                                                                  const updateVisibleRange = useCallback(() => {
                                                                                        const el = scrollRef.current;
                                                                                            if (!el) return;
                                                                                                const colWidth = 300;
                                                                                                    const startCol = Math.floor(el.scrollLeft / colWidth);
                                                                                                        const visibleCols = Math.floor(el.clientWidth / colWidth);
                                                                                                            setVisibleRange({
                                                                                                                      start: startCol,
                                                                                                                            end: Math.min(startCol + visibleCols, STATUSES.length - 1)
                                                                                                            });
                                                                                                        }, [scrollRef]);

                                                                                                          useEffect(() => {
                                                                                                                const el = scrollRef.current;
                                                                                                                    if (!el) return;
                                                                                                                        const handleScroll = () => {
                                                                                                                                  const maxScroll = el.scrollWidth - el.clientWidth;
                                                                                                                                        if (maxScroll > 0) {
                                                                                                                                                    setSliderValue((el.scrollLeft / maxScroll) * 100);
                                                                                                                                        }
                                                                                                                                              updateVisibleRange();
                                                                                                                                    };
                                                                                                                                        el.addEventListener('scroll', handleScroll);
                                                                                                                                            updateVisibleRange();
                                                                                                                                                return () => el.removeEventListener('scroll', handleScroll);
                                                                                                                                }, [scrollRef, updateVisibleRange]);

                                                                                                                                  const handleSliderChange = (e) => {
                                                                                                                                        const val = Number(e.target.value);
                                                                                                                                            setSliderValue(val);
                                                                                                                                                const el = scrollRef.current;
                                                                                                                                                    if (el) {
                                                                                                                                                              const maxScroll = el.scrollWidth - el.clientWidth;
                                                                                                                                                                    el.scrollLeft = (val / 100) * maxScroll;
                                                                                                                                                    }
                                                                                                                                                };

                                                                                                                                                  const startLabel = STATUSES[visibleRange.start]?.label || '';
                                                                                                                                                    const endLabel = STATUSES[visibleRange.end]?.label || '';

                                                                                                                                                      return (
                                                                                                                                                            <div className="flex items-center gap-3 px-2 py-2 bg-white border rounded-lg mb-3">
                                                                                                                                                                      <span className="text-sm font-medium text-slate-600 whitespace-nowrap">Pipeline Slider</span>
                                                                                                                                                                            <input
                                                                                                                                                                                    type="range"
                                                                                                                                                                                            min="0"
                                                                                                                                                                                                    max="100"
                                                                                                                                                                                                            value={sliderValue}
                                                                                                                                                                                                                    onChange={handleSliderChange}
                                                                                                                                                                                                                            className="flex-1 h-2 accent-orange-500 cursor-pointer"
                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                        <span className="text-xs text-slate-500 whitespace-nowrap min-w-[160px] text-right">
                                                                                                                                                                                                                                                    Showing: {startLabel} &rarr; {endLabel}
                                                                                                                                                                                                                                                          </span>
                                                                                                                                                                                                                                                              </div>
                                                                                                                                                      );
                                                                                                                                                      }

                                                                                                                                                      const runAIAssessment = async (grant, organization) => {
                                                                                                                                                          const analysisPrompt = `Analyze this opportunity for the applicant. Return a JSON object with keys: 'eligibility_score' (0-10), 'mission_alignment_score' (0-10), 'your_advantages' (array), 'potential_weaknesses' (array), and a 'recommendation' ('highly_recommend' or 'recommend' or 'consider' or 'not_recommended').
                                                                                                                                                          APPLICANT: ${JSON.stringify(organization)}
                                                                                                                                                          OPPORTUNITY: ${JSON.stringify(grant)}`;

                                                                                                                                                            const analysisResult = await client.integrations.Core.InvokeLLM({
                                                                                                                                                                    prompt: analysisPrompt,
                                                                                                                                                                        response_json_schema: {
                                                                                                                                                                                  type: "object",
                                                                                                                                                                                        properties: {
                                                                                                                                                                                                    eligibility_score: {type: "number"},
                                                                                                                                                                                                            mission_alignment_score: {type: "number"},
                                                                                                                                                                                                                    your_advantages: {type: "array", items: {type: "string"}},
                                                                                                                                                                                                                            potential_weaknesses: {type: "array", items: {type: "string"}},
                                                                                                                                                                                                                                    recommendation: {type: "string"}
                                                                                                                                                                                        }
                                                                                                                                                                                    }
                                                                                                                                                                                });

                                                                                                                                                                                  await client.entities.AiArtifact.create({
                                                                                                                                                                                        grant_id: grant.id,
                                                                                                                                                                                            kind: 'analysis',
                                                                                                                                                                                                content: JSON.stringify(analysisResult)
                                                                                                                                                                                                  });

                                                                                                                                                                                                    const urlToParse = grant.nofo_url || grant.url;
                                                                                                                                                                                                      if (urlToParse) {
                                                                                                                                                                                                            const parsingPrompt = `Extract all proposal sections and required attachments from this URL: ${urlToParse}. Return a JSON object with 'proposal_sections' (array of strings) and 'required_attachments' (array of strings).`;
                                                                                                                                                                                                                const extracted = await client.integrations.Core.InvokeLLM({
                                                                                                                                                                                                                          prompt: parsingPrompt,
                                                                                                                                                                                                                                add_context_from_internet: true,
                                                                                                                                                                                                                                      response_json_schema: {
                                                                                                                                                                                                                                                type: "object",
                                                                                                                                                                                                                                                        properties: {
                                                                                                                                                                                                                                                                      proposal_sections: { type: "array", items: { type: "string" } },
                                                                                                                                                                                                                                                                                required_attachments: { type: "array", items: { type: "string" } }
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                    const checklistItems = [
                                                                                                                                                                                                                                                              ...(extracted.proposal_sections || []).map(title => ({ grant_id: grant.id, title, type: 'task' })),
                                                                                                                                                                                                                                                                    ...(extracted.required_attachments || []).map(title => ({ grant_id: grant.id, title, type: 'doc' }))
                                                                                                                                                                                                                                                    ];
                                                                                                                                                                                                                                                        if (checklistItems.length > 0) {
                                                                                                                                                                                                                                                                  await client.entities.ChecklistItem.bulkCreate(checklistItems);
                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                    export default function KanbanBoard({ grants, organizations, onGrantUpdate, onGrantDelete }) {
                                                                                                                                                                                                                                                          const { toast } = useToast();
                                                                                                                                                                                                                                                            const queryClient = useQueryClient();
                                                                                                                                                                                                                                                              const scrollRef = useRef(null);

                                                                                                                                                                                                                                                                const { data: checklistItems = [] } = useQuery({
                                                                                                                                                                                                                                                                        queryKey: ['checklistItems'],
                                                                                                                                                                                                                                                                            queryFn: () => client.entities.ChecklistItem.list()
                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                const onDragEnd = async (result) => {
                                                                                                                                                                                                                                                                                        const { destination, source, draggableId } = result;
                                                                                                                                                                                                                                                                                            if (!destination || (destination.droppableId === source.droppableId && destination.index === source.index)) {
                                                                                                                                                                                                                                                                                                      return;
                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                const newStatus = destination.droppableId;
                                                                                                                                                                                                                                                                                                    onGrantUpdate(draggableId, { status: newStatus });

                                                                                                                                                                                                                                                                                                        if (newStatus === 'discovery') {
                                                                                                                                                                                                                                                                                                                  const grant = grants.find(g => g.id === draggableId);
                                                                                                                                                                                                                                                                                                                        const organization = organizations.find(o => o.id === grant.organization_id);
                                                                                                                                                                                                                                                                                                                              if (grant && organization) {
                                                                                                                                                                                                                                                                                                                                        toast({ title: "AI Assessment Started", description: `Analyzing ${grant.title}...` });
                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                              await runAIAssessment(grant, organization);
                                                                                                                                                                                                                                                                                                                                                                        queryClient.invalidateQueries({ queryKey: ['aiArtifact', grant.id] });
                                                                                                                                                                                                                                                                                                                                                                                  queryClient.invalidateQueries({ queryKey: ['checklistItems', grant.id] });
                                                                                                                                                                                                                                                                                                                                                                                            queryClient.invalidateQueries({ queryKey: ['checklistItems'] });
                                                                                                                                                                                                                                                                                                                                                                                                      toast({ title: "AI Assessment Complete", description: "Checklists and analysis have been generated." });
                                                                                                                                                                                                                                                                                                                                                } catch (e) {
                                                                                                                                                                                                                                                                                                                                                              toast({ variant: "destructive", title: "AI Assessment Failed", description: e.message });
                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                      const grantsByStatus = React.useMemo(() => {
                                                                                                                                                                                                                                                                                                                                            const acc = {};
                                                                                                                                                                                                                                                                                                                                            STATUSES.forEach((s) => { acc[s.value] = []; });
                                                                                                                                                                                                                                                                                                                                            const list = Array.isArray(grants) ? grants : [];
                                                                                                                                                                                                                                                                                                                                            for (const g of list) {
                                                                                                                                                                                                                                                                                                                                              // Normalize legacy statuses to their visible column; unknown/empty
                                                                                                                                                                                                                                                                                                                                              // status falls back to the first column so a grant is never dropped.
                                                                                                                                                                                                                                                                                                                                              const col = STATUS_ALIASES[g.status] || g.status;
                                                                                                                                                                                                                                                                                                                                              const bucket = acc[col] ? col : STATUSES[0].value;
                                                                                                                                                                                                                                                                                                                                              acc[bucket].push(g);
                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                            Object.keys(acc).forEach((k) => {
                                                                                                                                                                                                                                                                                                                                              acc[k].sort((a, b) => (a.starred === b.starred) ? 0 : a.starred ? -1 : 1);
                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                            return acc;
                                                                                                                                                                                                                                                                                                                                        }, [grants]);

                                                                                                                                                                                                                                                                                                                                          const handleStarToggle = (grant) => {
                                                                                                                                                                                                                                                                                                                                                onGrantUpdate(grant.id, { starred: !grant.starred });
                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                            const checklistProgress = React.useMemo(() => {
                                                                                                                                                                                                                                                                                                                                                    const progressMap = {};
                                                                                                                                                                                                                                                                                                                                                        grants.forEach(grant => {
                                                                                                                                                                                                                                                                                                                                                                  const items = checklistItems.filter(item => item.grant_id === grant.id);
                                                                                                                                                                                                                                                                                                                                                                        if (items.length === 0) { progressMap[grant.id] = null; return; }
                                                                                                                                                                                                                                                                                                                                                                              const completed = items.filter(item => item.status === 'done').length;
                                                                                                                                                                                                                                                                                                                                                                                    progressMap[grant.id] = Math.round((completed / items.length) * 100);
                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                            return progressMap;
                                                                                                                                                                                                                                                                                                                                                    }, [grants, checklistItems]);

                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                            <DragDropContext onDragEnd={onDragEnd}>
                                                                                                                                                                                                                                                                                                                                                                      <PipelineSlider scrollRef={scrollRef} />
                                                                                                                                                                                                                                                                                                                                                                            <div className="overflow-x-auto pb-4" ref={scrollRef}>
                                                                                                                                                                                                                                                                                                                                                                                        <div className="flex gap-4" style={{ minWidth: STATUSES.length * 300 }}>
                                                                                                                                                                                                                                                                                                                                                                                                      {STATUSES.map((status) => {
                                                                                                                                                                                                                                                                                                                                                                                                                    const statusGrants = grantsByStatus[status.value] || [];
                                                                                                                                                                                                                                                                                                                                                                                                                                const StatusIcon = status.icon;
                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div key={status.value} className="w-72 flex-shrink-0">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <Card className="shadow-lg border-0 bg-slate-50/50 h-full flex flex-col">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <CardHeader className={`${statusColors[status.value]} p-3`}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <CardTitle className="text-sm font-semibold flex items-center gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <StatusIcon className="w-4 h-4" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {status.label}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Badge variant="secondary" className="ml-auto">{statusGrants.length}</Badge>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </CardTitle>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </CardHeader>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Droppable droppableId={status.value}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {(provided, snapshot) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <CardContent
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ref={provided.innerRef}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {...provided.droppableProps}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              className={`p-2 space-y-2 flex-grow min-h-[200px] transition-colors ${snapshot.isDraggingOver ? 'bg-slate-100' : ''}`}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {statusGrants.map((grant, index) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const organization = organizations.find(o => o.id === grant.organization_id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Draggable key={grant.id} draggableId={grant.id} index={index}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {(provided, snapshot) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="block focus:outline-none focus:ring-2 focus:ring-blue-500 rounded-lg">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div ref={provided.innerRef} {...provided.draggableProps} {...provided.dragHandleProps}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <GrantCard
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              grant={grant}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    organization={organization}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onStatusChange={onGrantUpdate}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onStarToggle={() => handleStarToggle(grant)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onDelete={() => onGrantDelete(grant)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            isDragging={snapshot.isDragging}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  checklistProgress={checklistProgress[grant.id]}
                                      />
                                                                        </div>
                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </Draggable>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {provided.placeholder}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </CardContent>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Droppable>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Card>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </DragDropContext>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }